steps.change:
Replace the 6 read-cache field declarations (lines ~50-79) with ConcurrentHashMap equivalents:
  private val vertexByIdCache: ConcurrentHashMap<VertexKey, Optional<GraphVertex>> = ConcurrentHashMap(128)
  private val verticesByLabelCache: ConcurrentHashMap<LabelKey, List<GraphVertex>> = ConcurrentHashMap(128)
  private val neighborsCache: ConcurrentHashMap<NeighborKey, List<GraphVertex>> = ConcurrentHashMap(128)
  private val shortestPathCache: ConcurrentHashMap<PathKey, Optional<GraphPath>> = ConcurrentHashMap(128)
  private val allPathsCache: ConcurrentHashMap<PathKey, List<GraphPath>> = ConcurrentHashMap(128)
  private val edgesByLabelCache: ConcurrentHashMap<EdgeLabelKey, List<GraphEdge>> = ConcurrentHashMap(128)
Keep Optional wrappers for nullable value types (vertexByIdCache, shortestPathCache) — CHM disallows null values just like Caffeine does.

Update invalidateAll() and invalidateReads() to use .clear() instead of .invalidateAll() for all 6 read caches:
  private fun invalidateAll() {
      vertexByIdCache.clear(); verticesByLabelCache.clear(); neighborsCache.clear()
      shortestPathCache.clear(); allPathsCache.clear(); edgesByLabelCache.clear()
      createVertexMap.clear(); createEdgeMap.clear()
  }
  private fun invalidateReads() {
      vertexByIdCache.clear(); verticesByLabelCache.clear(); neighborsCache.clear()
      shortestPathCache.clear(); allPathsCache.clear(); edgesByLabelCache.clear()
  }

Rewrite the 6 read-path override methods to use CHM's computeIfAbsent (single lookup on miss, single lookup on hit) instead of Caffeine's cache.get(key){loader}:

  override fun findVertexById(label: String, id: GraphElementId): GraphVertex? {
      val key = VertexKey(label, id)
      return vertexByIdCache.computeIfAbsent(key) { Optional.ofNullable(delegate.findVertexById(label, id)) }.orElse(null)
  }

  override fun findVerticesByLabel(label: String, filter: Map<String, Any?>): List<GraphVertex> {
      val key = LabelKey(label, filter)
      return verticesByLabelCache.computeIfAbsent(key) { delegate.findVerticesByLabel(label, filter) }
  }

  override fun neighbors(startId: GraphElementId, options: NeighborOptions): List<GraphVertex> {
      val key = NeighborKey(startId, options)
      return neighborsCache.computeIfAbsent(key) { delegate.neighbors(startId, options) }
  }

  override fun shortestPath(fromId: GraphElementId, toId: GraphElementId, options: PathOptions): GraphPath? {
      val key = PathKey(fromId, toId, options)
      return shortestPathCache.computeIfAbsent(key) { Optional.ofNullable(delegate.shortestPath(fromId, toId, options)) }.orElse(null)
  }

  override fun allPaths(fromId: GraphElementId, toId: GraphElementId, options: PathOptions): List<GraphPath> {
      val key = PathKey(fromId, toId, options)
      return allPathsCache.computeIfAbsent(key) { delegate.allPaths(fromId, toId, options) }
  }

  override fun findEdgesByLabel(label: String, filter: Map<String, Any?>): List<GraphEdge> {
      val key = EdgeLabelKey(label, filter)
      return edgesByLabelCache.computeIfAbsent(key) { delegate.findEdgesByLabel(label, filter) }
  }

Note: we use computeIfAbsent (not getIfPresent + put) because it is the idiomatic CHM memoize pattern matching Caffeine's .get(key){loader} semantics (atomic put-if-absent). On a hit, computeIfAbsent still performs only a single get() under the hood (no mapping function invocation), so hot-path cost is ~5ns like a plain get().
